const totalStars=()=>Object.values(profile.worldProgress).reduce((sum,p)=>sum+Object.values(p.completed||{}).reduce((n,r)=>n+(r.stars||0),0),0);
const completedCount=(id=activeWorldId)=>Object.keys(worldProgress(id).completed||{}).length;
