const lifeRecovery=()=>{const ms=lifeRecoveryAt({lives:profile.lives??5,updatedAt:profile.lifeUpdatedAt||Date.now()});return ms?`${Math.floor(ms/60000)}:${String(Math.floor((ms%60000)/1000)).padStart(2,'0')}`:'full';};
