const playerAccuracy=()=>{const answers=profile.answerHistory||[];const sample=answers.slice(-50);return sample.length?sample.filter(Boolean).length/sample.length:(profile.totalAnswered?profile.totalCorrect/profile.totalAnswered:.65);};
function recommendedWorld(){const open=WORLDS.filter(world=>profile.unlockedWorlds.includes(world.id)&&completedCount(world.id)<100);if(!open.length)return WORLDS.find(world=>profile.unlockedWorlds.includes(world.id))||WORLDS[0];const accuracy=playerAccuracy();if(accuracy<.55)return open.find(world=>['general','space'].includes(world.id))||open[0];if(accuracy>.82)return open.sort((a,b)=>worldProgress(b.id).highestUnlocked-worldProgress(a.id).highestUnlocked)[0];return open.sort((a,b)=>completedCount(a.id)-completedCount(b.id))[0];}
function persist(){profile.lives=lives();if(profile.lives>=5)profile.lifeUpdatedAt=Date.now();saveGame(profile);renderHUD();}
function spendLife(){const before=lives();if(before>=5)profile.lifeUpdatedAt=Date.now();profile.lives=Math.max(0,before-1);persist();}
function addLife(){profile.lives=Math.min(5,lives()+1);if(profile.lives>=5)profile.lifeUpdatedAt=Date.now();persist();}
function renderHUD(){document.querySelector('#lives-count').textContent=lives();document.querySelector('#life-clock').textContent=lifeRecovery();document.querySelector('#coin-count').textContent=coins();document.querySelector('#profile-button').textContent=({nova:'🚀',luna:'🌙',comet:'☄️',orbit:'🪐',stardust:'✨'})[profile.character]||'A';document.querySelector('#sound-toggle').classList.toggle('muted',!profile.sound||!soundAllowed);document.querySelector('#sound-toggle').setAttribute('aria-label',`Sound effects ${profile.sound&&soundAllowed?'on':'off'}`);document.querySelector('#music-toggle')?.classList.toggle('muted',!profile.music);}
function toast(message){const region=document.querySelector('#toast-region');const el=document.createElement('div');el.className='toast';el.textContent=message;region.append(el);setTimeout(()=>el.remove(),2500);}
function playTone(kind){if(hostPaused||!profile.sound||!soundAllowed)return;try{audioContext ||= new AudioContext();if(audioContext.state==='suspended')audioContext.resume();const notes=kind==='correct'?[660,880]:kind==='wrong'?[240,180]:kind==='star'?[523,659,784]:[440];notes.forEach((frequency,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain(),start=audioContext.currentTime+i*.09;osc.type=kind==='wrong'?'triangle':(activeWorld().index%4===1?'triangle':'sine');osc.frequency.value=frequency*(1+activeWorld().index*.003);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.07,start+.02);gain.gain.exponentialRampToValueAtTime(.0001,start+.18);osc.connect(gain).connect(audioContext.destination);osc.start(start);osc.stop(start+.2);});}catch{}}
function startMusic(){
 if(hostPaused||!profile.music||!soundAllowed||typeof AudioContext==='undefined')return;
 const arrangement=WORLD_MUSIC[activeWorldId]||WORLD_MUSIC.space;
 if(musicNodes.length&&musicWorld===activeWorldId)return;
 if(musicNodes.length)stopMusic();
 try{
   audioContext ||= new AudioContext();
   if(audioContext.state==='suspended')audioContext.resume();
   const makeVoice=(type,frequency,volume)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type=type;osc.frequency.value=frequency;gain.gain.value=volume;osc.connect(gain).connect(audioContext.destination);osc.start();musicNodes.push({osc,gain});return {osc,gain};};
   const bass=makeVoice('sine',arrangement.root,.014);
   const pad=makeVoice(arrangement.wave,arrangement.root*2,.006);
   const melody=makeVoice(arrangement.wave,arrangement.root*4,.0001);
   musicWorld=activeWorldId;musicStep=0;
   const step=()=>{if(!musicNodes.length||!audioContext)return;const now=audioContext.currentTime,degree=arrangement.pattern[musicStep%arrangement.pattern.length],semitone=arrangement.scale[degree%arrangement.scale.length],bossShift=game?.boss&&musicStep%2===1?5:0,root=arrangement.root; bass.osc.frequency.setTargetAtTime(root*(musicStep%8===4?1.5:1),now,.35);pad.osc.frequency.setTargetAtTime(root*2*Math.pow(2,(arrangement.scale[(degree+2)%arrangement.scale.length]||7)/12),now,.5);melody.osc.frequency.setTargetAtTime(root*4*Math.pow(2,(semitone+bossShift)/12),now,.04);melody.gain.gain.cancelScheduledValues(now);melody.gain.gain.setTargetAtTime(.009,now,.035);melody.gain.gain.setTargetAtTime(.0001,now+arrangement.tempo/1250,.13);musicStep++;};
   step();musicLoop=setInterval(step,arrangement.tempo);
 }catch{stopMusic();}
}
function stopMusic(){if(musicLoop)clearInterval(musicLoop);musicLoop=null;for(const node of musicNodes){try{node.gain.gain.setTargetAtTime(.0001,audioContext.currentTime,.15);node.osc.stop(audioContext.currentTime+.6);}catch{}}musicNodes=[];musicWorld=null;}
function setWorldTheme(level=worldProgress().highestUnlocked||1){const world=activeWorld(),chapter=Math.floor((Math.max(1,level)-1)/10)+1,scene=resolveLevelTheme(world.id,chapter,level);document.documentElement.style.setProperty('--world-accent',world.accent);document.documentElement.style.setProperty('--world-deep',world.deep);document.documentElement.style.setProperty('--scene-accent',scene.palette.accent);document.documentElement.style.setProperty('--scene-deep',scene.palette.deep);return scene;}
function sceneAttributes(scene){return `data-art="${safeText(scene.worldId)}" data-layout="${scene.layout}" data-scene-id="${safeText(scene.sceneId)}" data-animation="${safeText(scene.animationPreset)}" data-interaction="${safeText(scene.interaction)}" style="--scene-accent:${safeText(scene.palette.accent)};--scene-deep:${safeText(scene.palette.deep)};--scene-layout:${scene.layout}"`;}
