function getInteractionBreakdownForLevel(level,type,daily=false,mode='adventure'){const pool=getQuestionPack(activeWorldId),spec=levelSpec(level),count=daily?3:mode==='perfect'?10:mode==='secret'?20:mode==='endless'?1:spec.questionCount,chapterId=Math.floor((Math.max(1,level)-1)/10)+1,chapterPool=mode==='adventure'?chapterQuestionPool(pool,{chapterId,count}):pool;const specializedPool=(type==='map-selection')?chapterPool.filter(q=>q.mapData):(type==='timeline-ordering')?chapterPool.filter(q=>q.timelineData):(type==='sequence-completion')?chapterPool.filter(q=>q.sequenceData):(type==='image-identification')?chapterPool.filter(q=>q.imageData):null;const specialCount=specializedPool?Math.min(count,specializedPool.length):0;const standardCount=Math.max(0,count-specialCount);const isPure=specialCount>=count;const isHybrid=specialCount>0&&specialCount<count;return{specialCount,standardCount,totalCount:count,isPure,isHybrid};}
