const characters=[['nova','🚀','Nova',0],['luna','🌙','Luna',80],['comet','☄️','Comet',120],['orbit','🪐','Orbit',180],['stardust','✨','Stardust',240]];
const world=WORLD_BY_ID[encyclopediaWorld]||WORLD_BY_ID.space,questions=getQuestionPack(world.id);
let section='';
if(collectionTab==='keepsakes')section=`<div class="collection-grid">${artifacts.map(([id,icon,name,description])=>{const unlocked=profile.unlockedArtifacts.includes(id);return `<article class="collectible ${unlocked?'':'locked'}"><span class="artifact">${unlocked?icon:'🔒'}</span><strong>${safeText(name)}</strong><small>${unlocked?safeText(description):'Keep exploring to discover it'}</small></article>`;}).join('')}</div><h2 class="collection-subhead">Achievements</h2><div class="world-list">${achievements.map(([id,label])=>`<div class="achievement ${profile.achievements.includes(id)?'earned':''}">${profile.achievements.includes(id)?'✓':'◇'} ${label}</div>`).join('')}</div>`;
if(collectionTab==='encyclopedia')section=`<div class="encyclopedia-tools"><label for="encyclopedia-world">Choose a world</label><select id="encyclopedia-world">${WORLDS.map(item=>`<option value="${item.id}" ${item.id===world.id?'selected':''}>${safeText(item.name)} · ${getQuestionPack(item.id).length} entries</option>`).join('')}</select></div><p class="encyclopedia-note">Seed entries are shown with their current reference link. Review the source before treating a fact as publication-ready.</p><div class="encyclopedia-list">${questions.map((q,index)=>`<details class="encyclopedia-entry"><summary><span>${String(index+1).padStart(3,'0')}</span>${safeText(q.q)}</summary><p><strong>${safeText(q.options?.find(option=>option.id===q.correctOptionId)?.text||q.a[q.correct])}</strong> · ${safeText(q.why)}</p><small>${safeText(q.topic)} · ${safeText(q.difficulty)} · Levels ${(q.eligibleLevels||[]).length?`${Math.min(...q.eligibleLevels)}–${Math.max(...q.eligibleLevels)}`:'—'} · <a href="${sourceUrl(q)}" target="_blank" rel="noopener noreferrer">${q.reviewStatus==='verified'?'Verified source':'Review source'}</a></small></details>`).join('')}</div>`;
